import sys
print(f"Python version: {sys.version}")

# Copy the essential parts from requests
is_py2 = sys.version_info[0] == 2
builtin_str = str
str_type = str
bytes_type = bytes
basestring = (str, bytes)

def to_key_val_list(value):
    """Convert dict-like objects to a list of tuples."""
    if value is None:
        return None
    if isinstance(value, (str, bytes, bool, int)):
        raise ValueError('cannot encode objects that are not 2-tuples')
    if isinstance(value, dict):
        value = value.items()
    return list(value)

def to_native_string(string, encoding='ascii'):
    out = None
    if isinstance(string, builtin_str):
        out = string
    else:
        if is_py2:
            out = string.encode(encoding)
        else:
            out = string.decode(encoding)
    return out

try:
    from urllib.parse import urlencode
except ImportError:
    from urllib import urlencode

def _encode_params(data):
    """Fixed version of _encode_params."""
    if isinstance(data, (str_type, bytes_type)):
        try:
            return to_native_string(data)
        except (UnicodeDecodeError, UnicodeEncodeError):
            return data
    elif hasattr(data, 'read'):
        return data
    elif hasattr(data, '__iter__'):
        result = []
        for k, vs in to_key_val_list(data):
            if isinstance(vs, basestring) or not hasattr(vs, '__iter__'):
                vs = [vs]
            for v in vs:
                if v is not None:
                    result.append(
                        (k.encode('utf-8') if isinstance(k, str) else k,
                         v.encode('utf-8') if isinstance(v, str) else v))
        return urlencode(result, doseq=True)
    else:
        return data

print("\n=== Test Cases ===")

# Test case 1: Issue from PR - binary payload with non-ASCII chars
data = u"ööö".encode("utf-8")
result = _encode_params(data)
print(f"1. Binary payload with UTF-8 chars: {result!r}")
assert isinstance(result, bytes), "Should return bytes for binary data"
print("   PASS: Binary data is returned as bytes")

# Test case 2: Original issue #2844 - bytes params for URL
params = b'test=foo'
result = _encode_params(params)
print(f"2. ASCII bytes params: {result!r}")
assert isinstance(result, str), "Should return string for ASCII bytes"
assert result == 'test=foo', "Should convert bytes to string correctly"
print("   PASS: ASCII bytes converted to string")

# Test case 3: Unicode string
data = "hello world"
result = _encode_params(data)
print(f"3. Unicode string: {result!r}")
assert isinstance(result, str), "Should return string"
print("   PASS: Unicode string preserved")

# Test case 4: Dict params (URL encoding)
params = {'key': 'value', 'key2': 'value2'}
result = _encode_params(params)
print(f"4. Dict params: {result!r}")
assert 'key=value' in result and 'key2=value2' in result, "Should encode dict"
print("   PASS: Dict params encoded correctly")

# Test case 5: Simulate URL query building with bytes params
query = "existing=1"
enc_params = _encode_params(b'test=foo')
if query:
    query = '%s&%s' % (query, enc_params)
else:
    query = enc_params
print(f"5. URL query with bytes params: {query!r}")
assert query == 'existing=1&test=foo', "Should build query correctly"
print("   PASS: URL query built correctly")

print("\n=== All tests passed! ===")
EOF
